<?php include("_security.php"); include("_config.php"); include("_globals.php"); include("_security_access.php"); include_once("_f_research.php"); requireResearchWriteAccess($isLoggedIn,$securityAccessLevel); $object=(int)($_POST["researchObjectId"]??0); $heading=trim($_POST["entryHeading"]??""); $text=trim($_POST["entryText"]??""); $date=trim($_POST["entryDate"]??""); $writer=$_SESSION["employeecode"]??""; $time=date("H:i"); $stmt=$conn->prepare("INSERT INTO research_entries (researchObjectId,entryHeading,entryText,entryWriter,entryDate,entryTime) VALUES (?,?,?,?,?,?)"); $stmt->bind_param("isssss",$object,$heading,$text,$writer,$date,$time); $stmt->execute();$stmt->close(); researchLog("Created","Research entry",$heading); header("Location: research_read_object.php?id=".$object); exit;
